<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Megaphone, Plus, Trash2, Copy, ExternalLink } from 'lucide-vue-next'
import { state, addPublication, removeItem } from '../lib/store'
import type { PublicationStatus } from '../lib/types'
const showForm=ref(false)
const search=ref('')
const message=ref('')
const form=reactive({week:'Semana 2',channel:'Instagram',topic:'',copy:'',audience:'Todos',status:'planejado' as PublicationStatus,result:'',url:''})
const filtered=computed(()=>state.publications.filter(p=>(p.topic+' '+p.channel+' '+p.week).toLowerCase().includes(search.value.toLowerCase())))
function submit(){if(!form.topic.trim())return;addPublication({...form,topic:form.topic.trim()});form.topic='';form.copy='';showForm.value=false}
function drop(id:string){if(confirm('Excluir publicação do calendário?'))removeItem('publications',id)}
async function copy(value:string){try {await navigator.clipboard.writeText(value);message.value='Texto copiado para a área de transferência.'}catch {message.value='Seu navegador não permitiu copiar automaticamente.'}}
function safeUrl(url:string){try{const target=new URL(url); return ['https:','http:'].includes(target.protocol)?target.href:null}catch{return null}}
</script>
<template>
<div class="view-enter"><div class="page-intro"><div><p class="eyebrow"><span class="eyebrow-line"></span> CONTEÚDO E DIVULGAÇÃO</p><h1>Publicações</h1><p class="page-subtitle">Ideias e textos da planilha, agora com status e resultados acompanháveis.</p></div><button class="btn btn-dark" @click="showForm=true"><Plus :size="17"/> Nova publicação</button></div>
<div class="surface"><div class="list-toolbar"><div class="search-field"><Megaphone :size="17"/><input v-model="search" aria-label="Buscar publicações" placeholder="Buscar conteúdo ou canal..."/></div><span class="item-counter">{{state.publications.filter(p=>p.status==='publicado').length}} publicadas / {{state.publications.length}} planejadas</span></div>
<div v-if="filtered.length" class="publication-grid"><article v-for="p in filtered" :key="p.id" class="publication-card"><div class="publication-meta"><span>{{p.week}}</span><b>{{p.channel}}</b><button class="icon-button danger" :aria-label="'Excluir '+p.topic" @click="drop(p.id)"><Trash2 :size="16"/></button></div><h2>{{p.topic}}</h2><p class="pub-audience">Para: {{p.audience}}</p><div class="field"><label>Texto sugerido</label><textarea v-model="p.copy" rows="3" maxlength="1000" :aria-label="'Texto de '+p.topic"/></div><button class="btn btn-outline btn-slim" @click="copy(p.copy)"><Copy :size="15"/> Copiar legenda</button><div class="form-row"><div class="field"><label>Status</label><select v-model="p.status"><option value="planejado">Planejado</option><option value="produzindo">Produzindo</option><option value="publicado">Publicado</option></select></div><div class="field"><label>Resultado</label><input v-model="p.result" maxlength="200" placeholder="Ex.: 3 conversas"/></div></div><div class="field"><label>Link publicado</label><div class="link-input"><input v-model="p.url" type="url" maxlength="500" placeholder="https://..."/><a v-if="safeUrl(p.url)" :href="safeUrl(p.url) || '#'" target="_blank" rel="noopener noreferrer" aria-label="Abrir publicação"><ExternalLink :size="17"/></a></div></div></article></div>
<div v-else class="empty"><Megaphone :size="25"/><b>Nenhuma publicação encontrada</b><p>Adicione uma ideia para seu calendário de divulgação.</p></div></div><p v-if="message" role="status" class="inline-notice">{{message}}</p>
<Teleport to="body"><div v-if="showForm" class="modal-backdrop" @click.self="showForm=false"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="pub-modal"><div class="modal-head"><h2 id="pub-modal">Nova publicação</h2><button class="icon-button" aria-label="Fechar" @click="showForm=false">✕</button></div><form @submit.prevent="submit"><div class="form-row"><div class="field"><label>Semana</label><select v-model="form.week"><option>Semana 1</option><option>Semana 2</option><option>Semana 3</option><option>Semana 4</option><option>Contínuo</option></select></div><div class="field"><label>Canal</label><select v-model="form.channel"><option>Instagram</option><option>WhatsApp Status</option><option>TikTok</option><option>Outro</option></select></div></div><div class="field"><label>Tema *</label><input v-model="form.topic" maxlength="160" required autofocus/></div><div class="field"><label>Texto da publicação</label><textarea v-model="form.copy" rows="3"/></div><div class="field"><label>Público</label><input v-model="form.audience" maxlength="140"/></div><div class="modal-actions"><button class="btn btn-outline" type="button" @click="showForm=false">Cancelar</button><button class="btn btn-dark">Adicionar</button></div></form></div></div></Teleport>
</div>
</template>
